import chess, chess.engine

def make(hashmb, threads):
    e = chess.engine.SimpleEngine.popen_uci("/usr/local/bin/stockfish")
    e.configure({"Threads": threads, "Hash": hashmb})
    return e

OPP = make(16, 1)
DEEP = make(2048, 8)

def opp_move(b):
    info = OPP.analyse(b, chess.engine.Limit(depth=18, time=1.0))
    return info["pv"][0], info["score"].white().score(mate_score=10000), info.get("depth")

def deep_move(b, t=1.5):
    info = DEEP.analyse(b, chess.engine.Limit(time=t))
    return info["pv"][0], info["score"].white().score(mate_score=10000), info.get("depth")

start = chess.Board("rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq - 0 1")

# Simulate games where WE play the deep move and OPP plays shallow, track eval divergence
def sim(first, plies=16, t=1.2):
    b = start.copy()
    b.push_uci(first)
    print(f"=== 1...{first}")
    for i in range(plies):
        if b.turn == chess.WHITE:
            om, osc, od = opp_move(b)
            dm, dsc, dd = deep_move(b, t)
            flag = "" if om == dm else "  ** DIVERGE **"
            print(f"  W opp {om}({osc},d{od}) deep {dm}({dsc},d{dd}){flag}")
            b.push(om)  # opponent plays its move
        else:
            dm, dsc, dd = deep_move(b, t)
            print(f"  B we {dm} (eval {dsc}, d{dd})")
            b.push(dm)
        if b.is_game_over():
            print("  game over", b.result()); break
    print("  FEN", b.fen())

for c in ["e7e5", "c7c5"]:
    sim(c, plies=14, t=1.0)
OPP.quit(); DEEP.quit()
