import chess, chess.engine
from collections import Counter

DEEP = chess.engine.SimpleEngine.popen_uci("/usr/local/bin/stockfish")
DEEP.configure({"Threads": 8, "Hash": 4096})

def opp_samples(b, n):
    out=[]
    for _ in range(n):
        e = chess.engine.SimpleEngine.popen_uci("/usr/local/bin/stockfish")
        e.configure({"Skill Level": 20})
        try: out.append(e.play(b, chess.engine.Limit(depth=18, time=1.0)).move.uci())
        finally: e.quit()
    return Counter(out)

def deep(b, t=2.0, mp=1):
    if mp==1:
        i = DEEP.analyse(b, chess.engine.Limit(time=t))
        return i["score"].white().score(mate_score=10000), i["pv"][0].uci()
    infos = DEEP.analyse(b, chess.engine.Limit(time=t), multipv=mp)
    return [(i["score"].white().score(mate_score=10000), i["pv"][0].uci()) for i in infos]

# Italian: 1.e4 e5 2.Nf3 Nc6 3.Bc4
b = chess.Board()
for m in ["e2e4","e7e5","g1f3","b8c6","f1c4"]: b.push_uci(m)
print("black choices:", deep(b, 2.0, mp=5))
# For each black try, sample white and eval
for mv in ["g8f6","f8c5","f8e7","d7d6","h7h6"]:
    b2 = b.copy(); b2.push_uci(mv)
    dist = opp_samples(b2, 4)
    evals = {}
    for om in dist:
        b3 = b2.copy(); b3.push_uci(om)
        evals[om] = deep(b3, 1.5)[0]
    print(f"  3...{mv}: white {dict(dist)} evals {evals}", flush=True)
DEEP.quit()
PY"}

